import{f as e,o as s,c as n,a2 as o}from"./chunks/framework.BUDOXiIz.js";const m=JSON.parse('{"title":"CoopApps — La landing de cada cooperativa, el stack y el modelo de datos","description":"","frontmatter":{},"headers":[],"relativePath":"presentacion-stakeholders/landing-stack-y-modelo-de-datos-para-imagenes.md","filePath":"presentacion-stakeholders/landing-stack-y-modelo-de-datos-para-imagenes.md","lastUpdated":null}'),t={name:"presentacion-stakeholders/landing-stack-y-modelo-de-datos-para-imagenes.md"};function r(i,a,l,c,d,p){return s(),n("div",null,[...a[0]||(a[0]=[o(`<h1 id="coopapps-—-la-landing-de-cada-cooperativa-el-stack-y-el-modelo-de-datos" tabindex="-1">CoopApps — La landing de cada cooperativa, el stack y el modelo de datos <a class="header-anchor" href="#coopapps-—-la-landing-de-cada-cooperativa-el-stack-y-el-modelo-de-datos" aria-label="Permalink to &quot;CoopApps — La landing de cada cooperativa, el stack y el modelo de datos&quot;">​</a></h1><p>Dieciséis imágenes en cuatro bloques: cómo cada cooperativa tiene su propia landing, qué tecnología se propone, cómo se organizan el backend y el frontend, y cómo es el modelo de datos. Todo sale de la especificación; ninguna imagen promete algo que no esté escrito.</p><table tabindex="0"><thead><tr><th>Dato</th><th>Valor</th></tr></thead><tbody><tr><td>Fecha</td><td>10-11-2026</td></tr><tr><td>Fuentes</td><td>M19 (landing, portal y app del socio: §1, §5.1, §9.1, §10.2, §18.1), T03 (marca por cooperativa: §7.B), T01 (stack, monorepo, módulos, outbox, colas, multitenancy y ambientes: §7.1 a §7.10), T05 (modelo de datos: §6, §7.0, §7.1, §7.8, §7.9 y §7.10), <code>00</code> §5, DEC-110 a DEC-113, DEC-064, DEC-075, DEC-100 y DEC-117</td></tr><tr><td>Datos</td><td>Todos los nombres, colores y dominios de ejemplo son ficticios (&quot;Cooperativa Ejemplo A&quot;, <code>coop-ejemplo-a</code>)</td></tr></tbody></table><hr><h2 id="_0-como-usar-este-documento" tabindex="-1">0. Cómo usar este documento <a class="header-anchor" href="#_0-como-usar-este-documento" aria-label="Permalink to &quot;0. Cómo usar este documento&quot;">​</a></h2><ol><li>Si la conversación es nueva, pegar primero el prompt de la sección 0.1.</li><li>Pedir las imágenes por código: &quot;Generá IMG-T01&quot;, &quot;Generá IMG-T02&quot;, etc.</li><li>Cada imagen trae una <strong>frase para decir</strong> en voz alta mientras se muestra.</li><li>Los bloques se pueden usar por separado: la landing (T01 a T04) sirve para una reunión comercial; el stack, el backend y el frontend (T05 a T10) para una reunión técnica; el modelo de datos (T11 a T16) para las dos.</li></ol><h3 id="_0-1-prompt-de-estilo-pegar-primero" tabindex="-1">0.1 Prompt de estilo (pegar primero) <a class="header-anchor" href="#_0-1-prompt-de-estilo-pegar-primero" aria-label="Permalink to &quot;0.1 Prompt de estilo (pegar primero)&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vas a dibujar dieciséis diapositivas para una reunión con directivos, stakeholders y responsables técnicos de una empresa de software para cooperativas de servicios públicos de Argentina. Muestran cómo cada cooperativa tiene su propia landing, la tecnología propuesta, la organización del backend y del frontend y el modelo de datos.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>El tono es seguro y sereno: el de alguien que ya diseñó el sistema y lo explica con claridad. Nada de adjetivos vacíos (&quot;revolucionario&quot;, &quot;increíble&quot;, &quot;de última generación&quot;), nada de signos de exclamación, nada de lenguaje publicitario.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Reglas obligatorias:</span></span>
<span class="line"><span>1. Usá SOLO los textos y números del documento. No inventes cifras, tecnologías, versiones ni promesas. Podés acortar sin cambiar el sentido.</span></span>
<span class="line"><span>2. Texto visible en español de Argentina. Los nombres de tecnologías vigentes (.NET, Azure SQL, React, Azure, etc.) van tal cual (DEC-111–112).</span></span>
<span class="line"><span>3. Generá cada imagen con código (HTML con SVG en Claude; Python con matplotlib en ChatGPT), 1920×1080 px. No uses el generador de imágenes para nada que tenga texto.</span></span>
<span class="line"><span>4. Paleta: gris carbón #2F343A, gris medio #6B7280, gris claro #E5E7EB, blanco #FFFFFF y verde cooperativo #2E7D32 como único acento. Ámbar #B7791F solo donde el documento lo indique. Sin rojo. Excepción: las imágenes de la landing usan los colores de marca de las cooperativas ficticias que indica cada prompt.</span></span>
<span class="line"><span>5. Diagramas limpios: cajas con esquinas apenas redondeadas, líneas finas, flechas simples, mucho espacio en blanco. Título grande (56 a 72 px), texto mínimo de 20 px. Como máximo un diagrama principal por imagen.</span></span>
<span class="line"><span>6. Tipografía sans serif limpia (Inter o similar); los nombres técnicos, si aparecen, en monoespaciada pequeña y gris.</span></span>
<span class="line"><span>7. Íconos de línea simples. Nada de robots, cerebros, cohetes, nubes brillantes, circuitos ni efectos futuristas.</span></span>
<span class="line"><span>8. En el modelo de datos, NO muestres nombres de campos ni tipos: cada entidad se muestra con su nombre en español y una frase corta que dice qué guarda.</span></span>
<span class="line"><span>9. Después de cada imagen, listá qué datos del documento usaste.</span></span>
<span class="line"><span>Esperá mi pedido por código (IMG-T01 a IMG-T16).</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><hr><h2 id="_1-las-dieciseis-imagenes" tabindex="-1">1. Las dieciséis imágenes <a class="header-anchor" href="#_1-las-dieciseis-imagenes" aria-label="Permalink to &quot;1. Las dieciséis imágenes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Código</th><th>Título de la imagen</th><th>Idea que deja</th></tr></thead><tbody><tr><td><strong>Bloque A — La landing de cada cooperativa</strong></td><td></td><td></td></tr><tr><td>IMG-T01</td><td>Una plataforma. Una landing por cooperativa.</td><td>Cada cooperativa tiene su sitio, con su dirección y su marca</td></tr><tr><td>IMG-T02</td><td>Qué tiene la landing.</td><td>Todo lo que el vecino necesita, sin iniciar sesión</td></tr><tr><td>IMG-T03</td><td>De la landing a la app, sin cambiar de cooperativa.</td><td>El recorrido del visitante al socio que se autogestiona</td></tr><tr><td>IMG-T04</td><td>La cooperativa publica su sitio, sin programadores.</td><td>Marca y contenido los maneja la cooperativa, con versiones</td></tr><tr><td><strong>Bloque B — El stack tecnológico</strong></td><td></td><td></td></tr><tr><td>IMG-T05</td><td>El stack, capa por capa.</td><td>Tecnología conocida, probada y de código abierto</td></tr><tr><td>IMG-T06</td><td>Una base, muchas cooperativas, ningún cruce.</td><td>El aislamiento entre cooperativas está en cada capa</td></tr><tr><td>IMG-T07</td><td>Del código a producción.</td><td>Contenedores, ambientes y un camino controlado a producción</td></tr><tr><td><strong>Bloque C — Backend y frontend</strong></td><td></td><td></td></tr><tr><td>IMG-T08</td><td>Cinco aplicaciones, un solo código.</td><td>Cómo se organiza el monorepo</td></tr><tr><td>IMG-T09</td><td>28 módulos con fronteras claras.</td><td>Un monolito modular: cada módulo es dueño de lo suyo</td></tr><tr><td>IMG-T10</td><td>Lo pesado no frena al usuario.</td><td>Eventos, colas y procesos en segundo plano</td></tr><tr><td><strong>Bloque D — El modelo de datos</strong></td><td></td><td></td></tr><tr><td>IMG-T11</td><td>1.058 tablas, ola por ola.</td><td>El tamaño del modelo y cómo se construye</td></tr><tr><td>IMG-T12</td><td>De la persona a la factura.</td><td>El corazón comercial del modelo</td></tr><tr><td>IMG-T13</td><td>De la factura al cobro.</td><td>Cuenta corriente, cobranza y mora</td></tr><tr><td>IMG-T14</td><td>Seis dominios, un solo modelo.</td><td>El mapa completo, por áreas</td></tr><tr><td>IMG-T15</td><td>Reglas que valen para todos los datos.</td><td>Las convenciones que protegen la información</td></tr><tr><td>IMG-T16</td><td>Pensado para crecer.</td><td>Volumen, particionado y archivo</td></tr></tbody></table><hr><h2 id="_2-bloque-a-—-la-landing-de-cada-cooperativa" tabindex="-1">2. Bloque A — La landing de cada cooperativa <a class="header-anchor" href="#_2-bloque-a-—-la-landing-de-cada-cooperativa" aria-label="Permalink to &quot;2. Bloque A — La landing de cada cooperativa&quot;">​</a></h2><h3 id="img-t01-—-una-plataforma-una-landing-por-cooperativa" tabindex="-1">IMG-T01 — Una plataforma. Una landing por cooperativa. <a class="header-anchor" href="#img-t01-—-una-plataforma-una-landing-por-cooperativa" aria-label="Permalink to &quot;IMG-T01 — Una plataforma. Una landing por cooperativa.&quot;">​</a></h3><p><strong>Respaldo:</strong> cada cooperativa tiene una landing propia con su marca, accesible por un subdominio <code>&amp;lt;cooperativa&gt;.&amp;lt;dominio de la plataforma&gt;</code> y, si lo desea, por su dominio propio. La landing nunca muestra la marca de otra cooperativa (M19 RF-POR-001 y RF-POR-021). Al entrar, el sistema reconoce la cooperativa por la dirección y carga su marca, su vocabulario, su oferta de servicios y su landing publicada (M19 §9.1). Hay además un punto de entrada general con un buscador de cooperativas por nombre o localidad (RF-POR-016).</p><p><strong>Frase para decir:</strong> &quot;Es una sola plataforma, pero el vecino entra al sitio de su cooperativa, con su nombre y sus colores. Nunca ve otra.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-T01 con código.</span></span>
<span class="line"><span>Título grande: &quot;Una plataforma. Una landing por cooperativa.&quot;</span></span>
<span class="line"><span>Composición: abajo, un bloque horizontal gris carbón, ancho, con el texto &quot;CoopApps · una sola plataforma&quot;. De él suben tres líneas finas hacia tres ventanas de navegador iguales en tamaño, en fila:</span></span>
<span class="line"><span>- Ventana 1: barra de dirección &quot;coop-ejemplo-a.&lt;dominio&gt;&quot;, marca &quot;Cooperativa Ejemplo A&quot; en azul #145DA0 con acento verde #2E8B57, portada con el título &quot;Conectate con tu cooperativa&quot; y tarjetas de Internet y Agua.</span></span>
<span class="line"><span>- Ventana 2: barra de dirección &quot;coop-ejemplo-b.&lt;dominio&gt;&quot;, marca &quot;Cooperativa Ejemplo B&quot; en violeta #6A1B9A con acento amarillo #F9A825, tarjetas de Gas y Energía.</span></span>
<span class="line"><span>- Ventana 3: barra de dirección &quot;www.cooperativa-c.com.ar&quot; con una etiqueta pequeña &quot;dominio propio&quot;, marca &quot;Cooperativa C&quot; en gris carbón con acento verde.</span></span>
<span class="line"><span>Las tres ventanas tienen la misma estructura (portada, servicios, accesos rápidos y botón de baja visible); solo cambian la marca, los colores y los servicios.</span></span>
<span class="line"><span>A la izquierda, una lupa con el texto pequeño &quot;Buscador de cooperativas por nombre o localidad&quot;.</span></span>
<span class="line"><span>Pie: &quot;Cada cooperativa con su dirección, su marca y sus servicios. Nunca la de otra&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h3 id="img-t02-—-que-tiene-la-landing" tabindex="-1">IMG-T02 — Qué tiene la landing. <a class="header-anchor" href="#img-t02-—-que-tiene-la-landing" aria-label="Permalink to &quot;IMG-T02 — Qué tiene la landing.&quot;">​</a></h3><p><strong>Respaldo:</strong> la landing se arma con bloques que la cooperativa activa y ordena (M19 RF-POR-002 y §10.2):</p><ul><li>portada;</li><li>servicios habilitados, cada uno con su ficha: planes con precio vigente e impuestos incluidos, requisitos, cobertura y botón &quot;Contratar&quot;;</li><li>accesos rápidos: Ingresar, Registrarme, Pagar, Botón de baja y Turnos;</li><li>consulta de cobertura por domicilio, con alternativa sin mapa;</li><li>noticias;</li><li>avisos de corte programados por zona;</li><li>trámites y requisitos, con los PDF descargables;</li><li>preguntas frecuentes;</li><li>contacto;</li><li>sucursales y horarios;</li><li>páginas legales.</li></ul><p>Sin iniciar sesión, el vecino puede:</p><ul><li>consultar cobertura;</li><li>pedir la baja y recibir un código de seguimiento dentro de las 24 h;</li><li>seguir su baja;</li><li>pagar con un código;</li><li>hacer una consulta.</li></ul><p>El botón de baja se ve en la portada sin desplazar la pantalla y en el pie de toda página (RF-POR-009 a RF-POR-014). La landing no muestra datos privados de ninguna persona (M19 §2.3).</p><p><strong>Frase para decir:</strong> &quot;El vecino encuentra todo sin crear una cuenta: qué servicios hay, cuánto cuestan, si llega a su casa, cómo hacer un trámite y cómo darse de baja.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-T02 con código.</span></span>
<span class="line"><span>Título grande: &quot;Qué tiene la landing.&quot;</span></span>
<span class="line"><span>Composición: en el centro, una maqueta grande de la landing de &quot;Cooperativa Ejemplo A&quot; (azul #145DA0, acento #2E8B57), en escritorio, dividida en franjas horizontales rotuladas, de arriba hacia abajo:</span></span>
<span class="line"><span>&quot;Portada&quot; · &quot;Accesos rápidos: Ingresar · Registrarme · Pagar · Botón de baja · Turnos&quot; · &quot;Servicios con precio vigente e impuestos incluidos&quot; · &quot;¿Llega a tu domicilio? Consulta de cobertura&quot; · &quot;Noticias y avisos de corte&quot; · &quot;Trámites y requisitos&quot; · &quot;Preguntas frecuentes · Contacto · Sucursales y horarios&quot; · &quot;Pie legal&quot;.</span></span>
<span class="line"><span>El botón de baja se destaca con borde ámbar #B7791F arriba, en la portada, y otra vez en el pie.</span></span>
<span class="line"><span>A la derecha de la maqueta, una columna titulada &quot;Sin iniciar sesión&quot; con cinco tildes verdes: &quot;Consultar cobertura&quot; · &quot;Pedir la baja y recibir un código en 24 h&quot; · &quot;Seguir la baja&quot; · &quot;Pagar con un código&quot; · &quot;Hacer una consulta&quot;.</span></span>
<span class="line"><span>Pie: &quot;Ningún dato privado en la parte pública&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="img-t03-—-de-la-landing-a-la-app-sin-cambiar-de-cooperativa" tabindex="-1">IMG-T03 — De la landing a la app, sin cambiar de cooperativa. <a class="header-anchor" href="#img-t03-—-de-la-landing-a-la-app-sin-cambiar-de-cooperativa" aria-label="Permalink to &quot;IMG-T03 — De la landing a la app, sin cambiar de cooperativa.&quot;">​</a></h3><p><strong>Respaldo:</strong> desde la ficha de un servicio, &quot;Contratar&quot; lleva al registro y después vuelve al formulario de ese servicio, siempre con la marca de la cooperativa (RF-POR-015). La app del socio es una aplicación web instalable en el celular (PWA), con el nombre, el ícono y los colores de la cooperativa (M19 §1 y §9.1). En ella el socio:</p><ul><li>contrata;</li><li>coordina la visita;</li><li>sigue la instalación;</li><li>firma la conformidad;</li><li>ve consumos y facturas;</li><li>paga en línea;</li><li>reclama con fotos;</li><li>suspende, reactiva y da de baja.</li></ul><p>Si además es empleado de la cooperativa, en la misma app tiene su espacio de empleado, sin mezclar datos (M19 §1).</p><p><strong>Frase para decir:</strong> &quot;El vecino entra por la landing, se registra y desde ese momento tiene a su cooperativa en el celular. Todo el tiempo ve la misma marca.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-T03 con código.</span></span>
<span class="line"><span>Título grande: &quot;De la landing a la app, sin cambiar de cooperativa.&quot;</span></span>
<span class="line"><span>Composición: un recorrido de izquierda a derecha en cuatro pantallas unidas por flechas, todas con la marca de &quot;Cooperativa Ejemplo A&quot; (azul #145DA0, acento #2E8B57):</span></span>
<span class="line"><span>1. Ventana de escritorio: &quot;Ficha de Internet · Plan de ejemplo · ARS 0.000 · Contratar&quot;.</span></span>
<span class="line"><span>2. Celular: &quot;Registrarme&quot; (formulario simple).</span></span>
<span class="line"><span>3. Celular: &quot;Formulario de Internet&quot; con la nota &quot;vuelve al servicio elegido&quot;.</span></span>
<span class="line"><span>4. Celular más grande: &quot;App del socio&quot; con ícono de la cooperativa en la pantalla de inicio del teléfono y la pantalla de inicio de la app (saldo ARS 0.000, próximo vencimiento, botón &quot;Pagar&quot;).</span></span>
<span class="line"><span>Debajo, una fila de ocho íconos de línea con rótulo: Contratar · Coordinar visita · Seguir la instalación · Firmar conformidad · Consumos y facturas · Pagar · Reclamar con fotos · Dar de baja.</span></span>
<span class="line"><span>Pie: &quot;La misma marca de punta a punta · Instalable en el celular · Espacio de empleado en la misma app&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h3 id="img-t04-—-la-cooperativa-publica-su-sitio-sin-programadores" tabindex="-1">IMG-T04 — La cooperativa publica su sitio, sin programadores. <a class="header-anchor" href="#img-t04-—-la-cooperativa-publica-su-sitio-sin-programadores" aria-label="Permalink to &quot;IMG-T04 — La cooperativa publica su sitio, sin programadores.&quot;">​</a></h3><p><strong>Respaldo:</strong> la cooperativa administra su marca y su landing desde el sistema.</p><ul><li><strong>Marca (T03 §7.B):</strong> nombre y sigla, color principal y de acento con control automático de contraste, logos por canal (sistema, app, landing, documentos y correo), logos por sucursal, pantalla de bienvenida, remitente de correos y de SMS, y variantes de marca para cada entidad jurídica en documentos y correos.</li><li><strong>Landing (RF-POR-003):</strong> pasa de borrador a revisión y de ahí a publicada, se previsualiza en escritorio y en celular, se puede programar la publicación y revertir a la versión anterior en menos de 1 minuto, con auditoría.</li><li><strong>Versiones:</strong> existe una sola versión publicada a la vez.</li></ul><p><strong>Frase para decir:</strong> &quot;Cambiar una noticia, un banner o el logo no requiere llamar a nadie. Y si algo sale mal, se vuelve a la versión anterior en un minuto.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-T04 con código.</span></span>
<span class="line"><span>Título grande: &quot;La cooperativa publica su sitio, sin programadores.&quot;</span></span>
<span class="line"><span>Composición en dos mitades:</span></span>
<span class="line"><span>- Izquierda, &quot;Su marca&quot;: una tarjeta de configuración sobria con muestras de color (principal y acento) y un pequeño indicador verde &quot;contraste verificado&quot;; debajo, cinco miniaturas de logo rotuladas &quot;Sistema · App · Landing · Documentos · Correo&quot;; y tres líneas: &quot;Logos por sucursal&quot; · &quot;Pantalla de bienvenida&quot; · &quot;Variantes por entidad jurídica en documentos y correos&quot;.</span></span>
<span class="line"><span>- Derecha, &quot;Su landing&quot;: una línea de estados con tres pasos &quot;Borrador → En revisión → Publicada&quot;; debajo, dos miniaturas de vista previa &quot;Escritorio&quot; y &quot;Celular&quot;; y un botón gris con flecha circular &quot;Volver a la versión anterior · menos de 1 minuto&quot;.</span></span>
<span class="line"><span>Pie: &quot;Una sola versión publicada a la vez · Cada cambio queda auditado&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><hr><h2 id="_3-bloque-b-—-el-stack-tecnologico" tabindex="-1">3. Bloque B — El stack tecnológico <a class="header-anchor" href="#_3-bloque-b-—-el-stack-tecnologico" aria-label="Permalink to &quot;3. Bloque B — El stack tecnológico&quot;">​</a></h2><h3 id="img-t05-—-el-stack-capa-por-capa" tabindex="-1">IMG-T05 — El stack, capa por capa. <a class="header-anchor" href="#img-t05-—-el-stack-capa-por-capa" aria-label="Permalink to &quot;IMG-T05 — El stack, capa por capa.&quot;">​</a></h3><p><strong>Respaldo:</strong> stack acordado con GoodApps (DEC-111, DEC-112; <code>00</code> §5, T01).</p><table tabindex="0"><thead><tr><th>Capa</th><th>Tecnología</th></tr></thead><tbody><tr><td>Pantallas (sistema, app del socio y landing)</td><td>React 19, Vite, TypeScript, Tailwind 4, shadcn/Radix; PWA instalable; mapas con Leaflet</td></tr><tr><td>Servidor</td><td>.NET 10, ASP.NET Core, EF Core; validación alineada a contratos y zod en front</td></tr><tr><td>Trabajo en segundo plano</td><td>Azure Queue Storage; workers .NET; Redis en Azure donde aplique</td></tr><tr><td>Datos</td><td>Azure SQL (base compartida multitenant, transacciones, integridad referencial)</td></tr><tr><td>Archivos</td><td>Azure Blob privado; URLs firmadas de corta duración</td></tr><tr><td>Seguridad de acceso</td><td>OpenIddict, 2FA, sesión federada según T02</td></tr><tr><td>Mensajería</td><td>Correo, push, WhatsApp y canales acordados en T02/T09</td></tr><tr><td>Documentos</td><td>Excel, PDF y códigos QR</td></tr><tr><td>IA</td><td>Proveedores con medición por cooperativa; propone, no ejecuta solo (P6)</td></tr><tr><td>Observación</td><td>Application Insights, logs estructurados, OpenTelemetry</td></tr><tr><td>Pruebas</td><td>Unitarias, integración SQL, Playwright, k6</td></tr><tr><td>Empaquetado</td><td>Contenedores en <strong>Microsoft Azure</strong> (Container Apps)</td></tr></tbody></table><p>UI según design system CoopApps (T03) con componentes shadcn/Radix.</p><p><strong>Frase para decir:</strong> &quot;CoopApps se construye sobre .NET y Azure, con una base relacional segura y pantallas React modernas para el equipo y para el socio.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-T05 con código.</span></span>
<span class="line"><span>Título grande: &quot;El stack, capa por capa.&quot;</span></span>
<span class="line"><span>Composición: una pila vertical de seis franjas horizontales anchas, de arriba hacia abajo, cada una con el nombre de la capa a la izquierda (texto gris carbón) y las tecnologías a la derecha como etiquetas redondeadas de borde verde:</span></span>
<span class="line"><span>1. &quot;Pantallas&quot; — React 19 · Vite · TypeScript · Tailwind · PWA · Leaflet</span></span>
<span class="line"><span>2. &quot;Servidor&quot; — .NET 10 · ASP.NET Core · EF Core</span></span>
<span class="line"><span>3. &quot;Segundo plano&quot; — Azure Queue · Workers .NET</span></span>
<span class="line"><span>4. &quot;Datos&quot; — Azure SQL (multitenant, transacciones)</span></span>
<span class="line"><span>5. &quot;Archivos&quot; — Azure Blob</span></span>
<span class="line"><span>6. &quot;Empaquetado y nube&quot; — Microsoft Azure · Container Apps</span></span>
<span class="line"><span>A la derecha de la pila, una columna vertical fina que atraviesa todas las capas, rotulada &quot;Transversal&quot;: Seguridad (OpenIddict, 2FA) · Observación (Application Insights) · Pruebas (integración SQL, Playwright, k6) · IA con medición por cooperativa.</span></span>
<span class="line"><span>Pie: &quot;Stack GoodApps · Azure · Diseño CoopApps (T03)&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h3 id="img-t06-—-una-base-muchas-cooperativas-ningun-cruce" tabindex="-1">IMG-T06 — Una base, muchas cooperativas, ningún cruce. <a class="header-anchor" href="#img-t06-—-una-base-muchas-cooperativas-ningun-cruce" aria-label="Permalink to &quot;IMG-T06 — Una base, muchas cooperativas, ningún cruce.&quot;">​</a></h3><p><strong>Respaldo:</strong> todas las cooperativas comparten una sola base <strong>Azure SQL</strong>, y cada dato lleva la cooperativa a la que pertenece (<strong>DEC-110</strong>). El aislamiento se controla en cada capa (T01 §7.8):</p><ul><li><strong>Acceso:</strong> el token de acceso dice de qué cooperativa es el usuario.</li><li><strong>Consultas:</strong> ninguna consulta se ejecuta sin la cooperativa; si falta, la operación se rechaza.</li><li><strong>Índices:</strong> todos los índices empiezan por la cooperativa.</li><li><strong>Transacciones:</strong> una transacción no puede mezclar cooperativas.</li><li><strong>Archivos, caché, procesos y eventos:</strong> todos llevan la cooperativa.</li><li><strong>Copias de seguridad:</strong> se restaura una cooperativa sin tocar a las demás.</li><li><strong>Inteligencia artificial:</strong> solo ve datos de la cooperativa que la usa.</li></ul><p>Las pruebas automáticas de aislamiento corren en cada cambio y cubren toda colección nueva (T05 §7.1.2).</p><p><strong>Frase para decir:</strong> &quot;Es una sola base, pero cada dato sabe de quién es. El sistema no deja que una cooperativa vea lo de otra, y lo probamos en cada cambio.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-T06 con código.</span></span>
<span class="line"><span>Título grande: &quot;Una base, muchas cooperativas, ningún cruce.&quot;</span></span>
<span class="line"><span>Composición: en el centro, un cilindro de base de datos grande en gris carbón rotulado &quot;Una sola base&quot;. Dentro, documentos pequeños apilados en tres colores suaves con una etiqueta en cada uno: &quot;Cooperativa A&quot;, &quot;Cooperativa B&quot;, &quot;Cooperativa C&quot;, separados por líneas finas verdes.</span></span>
<span class="line"><span>Alrededor del cilindro, en círculo, ocho controles con un candado verde pequeño y una línea corta cada uno:</span></span>
<span class="line"><span>&quot;Acceso: el token dice la cooperativa&quot; · &quot;Consultas: sin cooperativa, se rechaza&quot; · &quot;Índices: empiezan por la cooperativa&quot; · &quot;Transacciones: nunca mezclan&quot; · &quot;Archivos y caché: separados&quot; · &quot;Procesos y eventos: llevan la cooperativa&quot; · &quot;Copias: se restaura una sin tocar las demás&quot; · &quot;IA: solo ve lo de su cooperativa&quot;.</span></span>
<span class="line"><span>Pie: &quot;Pruebas automáticas de aislamiento en cada cambio&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="img-t07-—-del-codigo-a-produccion" tabindex="-1">IMG-T07 — Del código a producción. <a class="header-anchor" href="#img-t07-—-del-codigo-a-produccion" aria-label="Permalink to &quot;IMG-T07 — Del código a producción.&quot;">​</a></h3><p><strong>Respaldo:</strong> un mismo Dockerfile genera cinco imágenes: API, procesos en segundo plano, sistema de gestión, app del socio y landing (T01 §7.10). Cada cooperativa se resuelve por su dirección:</p><ul><li><code>/</code> es la landing;</li><li><code>/app/</code> es la app del socio;</li><li><code>/admin/</code> es el sistema de gestión;</li><li><code>/api</code> es el servidor.</li></ul><p>En local todo se levanta con un solo comando (<code>docker compose up</code>). Hay siete ambientes:</p><ul><li>local;</li><li>pruebas automáticas;</li><li>desarrollo;</li><li>preproducción;</li><li>prueba de configuración de cada cooperativa;</li><li>demostración;</li><li>producción.</li></ul><p>Cada cambio pasa por estos controles antes de llegar a producción:</p><ol><li>revisión de código y de fronteras entre módulos;</li><li>pruebas con base real;</li><li>suite de aislamiento;</li><li>escaneo de seguridad;</li><li>preproducción con pruebas de punta a punta y de carga;</li><li>aprobación;</li><li>despliegue por anillos.</li></ol><p><strong>Frase para decir:</strong> &quot;Cada cambio pasa por los mismos controles antes de llegar a la cooperativa, y todas tienen siempre la misma versión.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-T07 con código.</span></span>
<span class="line"><span>Título grande: &quot;Del código a producción.&quot;</span></span>
<span class="line"><span>Composición en tres franjas horizontales:</span></span>
<span class="line"><span>1. Arriba, &quot;Cinco imágenes, un solo código&quot;: cinco cajas iguales en fila (API · Segundo plano · Sistema de gestión · App del socio · Landing), cada una con un ícono de contenedor.</span></span>
<span class="line"><span>2. En el medio, &quot;Cada cooperativa, por su dirección&quot;: la dirección &quot;coop-ejemplo-a.&lt;dominio&gt;&quot; en monoespaciada y, debajo, cuatro ramas: &quot;/ → Landing&quot; · &quot;/app/ → App del socio&quot; · &quot;/admin/ → Sistema de gestión&quot; · &quot;/api → Servidor&quot;.</span></span>
<span class="line"><span>3. Abajo, &quot;El camino a producción&quot;: una línea de pasos con flechas: &quot;Revisión y fronteras&quot; → &quot;Pruebas con base real&quot; → &quot;Aislamiento&quot; → &quot;Seguridad&quot; → &quot;Preproducción y carga&quot; → &quot;Aprobación&quot; → &quot;Producción por anillos&quot;. El último paso en verde.</span></span>
<span class="line"><span>Pie: &quot;Siete ambientes · Un comando para levantar todo en local · La misma versión para todas las cooperativas&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><hr><h2 id="_4-bloque-c-—-backend-y-frontend" tabindex="-1">4. Bloque C — Backend y frontend <a class="header-anchor" href="#_4-bloque-c-—-backend-y-frontend" aria-label="Permalink to &quot;4. Bloque C — Backend y frontend&quot;">​</a></h2><h3 id="img-t08-—-cinco-aplicaciones-un-solo-codigo" tabindex="-1">IMG-T08 — Cinco aplicaciones, un solo código. <a class="header-anchor" href="#img-t08-—-cinco-aplicaciones-un-solo-codigo" aria-label="Permalink to &quot;IMG-T08 — Cinco aplicaciones, un solo código.&quot;">​</a></h3><p><strong>Respaldo:</strong> todo vive en un solo repositorio (monorepo; T01 §7.3).</p><table tabindex="0"><thead><tr><th>Pieza</th><th>Qué es</th></tr></thead><tbody><tr><td><code>apps/api</code></td><td>El servidor: recibe los pedidos, valida permisos y ejecuta las operaciones</td></tr><tr><td><code>apps/worker</code></td><td>Los procesos en segundo plano: lotes, integraciones, notificaciones, exportaciones</td></tr><tr><td><code>apps/admin</code></td><td>El sistema de gestión que usa el personal de la cooperativa</td></tr><tr><td><code>apps/pwa</code></td><td>La app del socio, del empleado y de campo, instalable en el celular</td></tr><tr><td><code>apps/landing</code></td><td>El sitio público de cada cooperativa</td></tr></tbody></table><p>Hay además cuatro paquetes compartidos:</p><ul><li><strong>contratos de datos:</strong> los mismos esquemas en servidor y pantallas, más dinero, fechas y catálogos;</li><li><strong>diseño visual propio:</strong> tablas, asistente de importación de Excel, ventanas y avisos;</li><li><strong>diccionario de textos:</strong> cada cooperativa puede usar su propio vocabulario;</li><li><strong>conectores de integración.</strong></li></ul><p>El servidor y los procesos en segundo plano usan exactamente los mismos módulos.</p><p><strong>Frase para decir:</strong> &quot;Hay una sola fuente de código. El servidor, las pantallas y la app comparten las mismas reglas, así no se contradicen.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-T08 con código.</span></span>
<span class="line"><span>Título grande: &quot;Cinco aplicaciones, un solo código.&quot;</span></span>
<span class="line"><span>Composición: un gran rectángulo con borde gris rotulado &quot;Un solo repositorio&quot;. Dentro, dos filas:</span></span>
<span class="line"><span>- Fila superior, &quot;Backend&quot;: dos cajas grandes gris carbón, &quot;Servidor (API)&quot; y &quot;Procesos en segundo plano&quot;, unidas por una franja verde &quot;mismos módulos&quot;.</span></span>
<span class="line"><span>- Fila del medio, &quot;Frontend&quot;: tres cajas en verde claro, &quot;Sistema de gestión&quot;, &quot;App del socio, empleado y campo&quot; y &quot;Landing pública&quot;.</span></span>
<span class="line"><span>- Fila inferior, &quot;Compartido por todos&quot;: cuatro cajas finas, &quot;Contratos de datos&quot; · &quot;Diseño visual propio&quot; · &quot;Diccionario de textos&quot; · &quot;Conectores de integración&quot;, con líneas finas que suben hacia el backend y el frontend.</span></span>
<span class="line"><span>Pie: &quot;Las mismas reglas en el servidor y en las pantallas&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="img-t09-—-28-modulos-con-fronteras-claras" tabindex="-1">IMG-T09 — 28 módulos con fronteras claras. <a class="header-anchor" href="#img-t09-—-28-modulos-con-fronteras-claras" aria-label="Permalink to &quot;IMG-T09 — 28 módulos con fronteras claras.&quot;">​</a></h3><p><strong>Respaldo:</strong> el backend es un <strong>monolito modular</strong> (DEC-003; T01 §7.2 y §7.4). Es un solo sistema dividido en 28 módulos: 19 de negocio y 9 de plataforma.</p><ul><li><strong>Negocio:</strong> personas, catálogo, medición, tarifas, facturación, fiscal, cobranza, mora, atención, técnica, ventas, compras, stock, tesorería, contabilidad, sueldos, institucional, servicios sociales y portal.</li><li><strong>Plataforma:</strong> plataforma, identidad, marca, configuración, integraciones, migración, workflow, comunicaciones y reportes.</li></ul><p>Las reglas entre módulos son estas:</p><ul><li><strong>Cada módulo es dueño de sus datos:</strong> solo él los escribe.</li><li><strong>Los módulos se hablan por dos vías:</strong> un pedido directo o un evento.</li><li><strong>Las fronteras se controlan solas:</strong> una revisión automática impide que un módulo toque los datos de otro.</li><li><strong>El sistema puede separarse si hace falta:</strong> si un módulo necesita crecer aparte, se separa sin reescribir a los demás.</li></ul><p><strong>Frase para decir:</strong> &quot;Es un solo sistema, fácil de operar, pero dividido por dentro como si fueran 28. Ningún módulo toca los datos de otro.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-T09 con código.</span></span>
<span class="line"><span>Título grande: &quot;28 módulos con fronteras claras.&quot;</span></span>
<span class="line"><span>Composición: una cuadrícula de 28 fichas pequeñas, todas del mismo tamaño, agrupadas en dos zonas:</span></span>
<span class="line"><span>- Zona grande &quot;Negocio · 19&quot; (fichas con borde verde): Personas · Catálogo · Medición · Tarifas · Facturación · Fiscal · Cobranza · Mora · Atención · Técnica · Ventas · Compras · Stock · Tesorería · Contabilidad · Sueldos · Institucional · Servicios sociales · Portal.</span></span>
<span class="line"><span>- Zona &quot;Plataforma · 9&quot; (fichas en gris carbón): Plataforma · Identidad · Marca · Configuración · Integraciones · Migración · Workflow · Comunicaciones · Reportes.</span></span>
<span class="line"><span>Entre dos fichas de ejemplo (Facturación y Cobranza), dos flechas finas rotuladas &quot;pedido directo&quot; y &quot;evento&quot;; y un candado pequeño sobre Facturación con la nota &quot;sus datos solo los escribe él&quot;.</span></span>
<span class="line"><span>A la derecha, tres afirmaciones con tilde verde: &quot;Cada módulo es dueño de sus datos&quot; · &quot;Se hablan por pedidos o eventos&quot; · &quot;Una revisión automática controla las fronteras&quot;.</span></span>
<span class="line"><span>Pie: &quot;Un solo sistema para operar · Separable si algún día un módulo necesita crecer aparte&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="img-t10-—-lo-pesado-no-frena-al-usuario" tabindex="-1">IMG-T10 — Lo pesado no frena al usuario. <a class="header-anchor" href="#img-t10-—-lo-pesado-no-frena-al-usuario" aria-label="Permalink to &quot;IMG-T10 — Lo pesado no frena al usuario.&quot;">​</a></h3><p><strong>Respaldo:</strong> ningún proceso masivo corre mientras el usuario espera (T01 ARQ-PLA-11).</p><ul><li><strong>Mismo momento:</strong> cuando un módulo hace un cambio, guarda el cambio y el evento que lo anuncia juntos. Si uno falla, falla el otro (outbox).</li><li><strong>Sin duplicados:</strong> los consumidores procesan cada evento una sola vez, aunque llegue dos veces.</li><li><strong>Ocho colas:</strong> el trabajo se reparte según su tipo: <ul><li>interactivo;</li><li>integraciones (ARCA, pasarelas, bancos);</li><li>eventos;</li><li>notificaciones;</li><li>lotes (facturación, mora);</li><li>exportaciones;</li><li>IA;</li><li>mantenimiento.</li></ul></li><li><strong>Límite por cooperativa:</strong> cada cola tiene un tope por cooperativa, para que una cooperativa grande no frene a las demás.</li><li><strong>Control de los procesos largos:</strong> se pausan, se cancelan y se retoman desde donde quedaron.</li><li><strong>Fallas:</strong> si algo falla, se reintenta. Si sigue fallando, pasa a una bandeja y genera una alerta (T01 §7.6).</li></ul><p><strong>Frase para decir:</strong> &quot;Cuando la cooperativa factura veinticinco mil cuentas, la persona que atiende en el mostrador no lo nota.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-T10 con código.</span></span>
<span class="line"><span>Título grande: &quot;Lo pesado no frena al usuario.&quot;</span></span>
<span class="line"><span>Composición de izquierda a derecha:</span></span>
<span class="line"><span>1. Una caja &quot;Cambio en un módulo&quot; con dos hojas dentro, &quot;el dato&quot; y &quot;su evento&quot;, y la etiqueta &quot;se guardan juntos&quot;.</span></span>
<span class="line"><span>2. Una flecha hacia un embudo &quot;Despachador&quot; y, de él, ocho carriles horizontales apilados, cada uno con su nombre: Interactivo · Integraciones · Eventos · Notificaciones · Lotes · Exportaciones · IA · Mantenimiento. El carril de Lotes es más ancho y lleva la nota &quot;facturación y mora&quot;.</span></span>
<span class="line"><span>3. A la derecha de los carriles, tres afirmaciones con tilde verde: &quot;Cada evento se procesa una sola vez&quot; · &quot;Tope por cooperativa: una grande no frena a las demás&quot; · &quot;Pausar, cancelar y retomar donde quedó&quot;.</span></span>
<span class="line"><span>Abajo, en ámbar, una caja chica: &quot;Si falla: reintento; si sigue fallando, bandeja y alerta&quot;.</span></span>
<span class="line"><span>Pie: &quot;Ningún proceso masivo corre mientras el usuario espera&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><hr><h2 id="_5-bloque-d-—-el-modelo-de-datos" tabindex="-1">5. Bloque D — El modelo de datos <a class="header-anchor" href="#_5-bloque-d-—-el-modelo-de-datos" aria-label="Permalink to &quot;5. Bloque D — El modelo de datos&quot;">​</a></h2><h3 id="img-t11-—-1-058-tablas-ola-por-ola" tabindex="-1">IMG-T11 — 1.058 tablas, ola por ola. <a class="header-anchor" href="#img-t11-—-1-058-tablas-ola-por-ola" aria-label="Permalink to &quot;IMG-T11 — 1.058 tablas, ola por ola.&quot;">​</a></h3><p><strong>Respaldo:</strong> el modelo tiene <strong>1.058 tablas</strong> en Azure SQL (<code>07-catalogo-tablas-sql.md</code>, DDL en <code>07-ddl</code>). Cada una tiene un módulo dueño, sus claves, sus índices, su clasificación de datos y su ola de creación (T05 §1 y §7.9). Se crean a medida que se construye cada ola:</p><table tabindex="0"><thead><tr><th>Ola</th><th>Tablas</th></tr></thead><tbody><tr><td>O0 Cimientos</td><td>63</td></tr><tr><td>O1 Plataforma, identidad y configuración</td><td>134</td></tr><tr><td>O2 Personas, catálogo, atención y comunidad</td><td>138</td></tr><tr><td>O3 Internet: técnica y equipos</td><td>64</td></tr><tr><td>O4 Tarifas, facturación y ARCA</td><td>96</td></tr><tr><td>O5 Cobranza y núcleo contable</td><td>104</td></tr><tr><td>O6 Mora</td><td>35</td></tr><tr><td>O7 Servicios medidos</td><td>72</td></tr><tr><td>O8 ERP administrativo</td><td>100</td></tr><tr><td>O9 Sueldos</td><td>65</td></tr><tr><td>O10 Institucional, social, telefonía y fabricación</td><td>125</td></tr><tr><td>O11 BI, migración y paralelo</td><td>62</td></tr></tbody></table><p><strong>Frase para decir:</strong> &quot;El modelo de datos está completo: más de mil tablas, cada una con su dueño y su momento de construcción.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-T11 con código.</span></span>
<span class="line"><span>Título grande: &quot;1.058 tablas, ola por ola.&quot;</span></span>
<span class="line"><span>Composición: a la izquierda, el número &quot;1.058&quot; enorme en verde con el rótulo &quot;tablas, cada una con su dueño&quot;. A la derecha, un gráfico de barras verticales sobrio, una barra por ola, en gris carbón, con la cifra arriba y el nombre corto debajo:</span></span>
<span class="line"><span>O0 Cimientos 63 · O1 Plataforma 134 · O2 Personas y atención 138 · O3 Internet 64 · O4 Facturación y ARCA 96 · O5 Cobranza y contabilidad 104 · O6 Mora 35 · O7 Servicios medidos 72 · O8 ERP 100 · O9 Sueldos 65 · O10 Institucional y social 125 · O11 BI y migración 62.</span></span>
<span class="line"><span>Sin ejes recargados ni cuadrícula; solo las barras y sus cifras.</span></span>
<span class="line"><span>Pie: &quot;Cada tabla se crea en la ola de su módulo, con sus índices y sus pruebas de aislamiento&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="img-t12-—-de-la-persona-a-la-factura" tabindex="-1">IMG-T12 — De la persona a la factura. <a class="header-anchor" href="#img-t12-—-de-la-persona-a-la-factura" aria-label="Permalink to &quot;IMG-T12 — De la persona a la factura.&quot;">​</a></h3><p><strong>Respaldo:</strong> el núcleo comercial del modelo (T05 §7.10), explicado sin campos:</p><ul><li><strong>Persona:</strong> cualquier persona física o jurídica, una sola vez en el sistema aunque cumpla varios roles (socio, proveedor, chofer…) (DEC-097).</li><li><strong>Titular:</strong> la persona como responsable de cuentas.</li><li><strong>Cuenta o suministro:</strong> agrupa los servicios de un titular en un lugar.</li><li><strong>Inmueble y punto de servicio:</strong> dónde se presta el servicio.</li><li><strong>Contrato de servicio:</strong> un servicio concreto con su plan vigente. Cada contrato puede tener equipos asignados y personas adheridas.</li><li><strong>Punto de medición, lectura y consumo:</strong> lo que marca el medidor y lo que se consumió.</li><li><strong>Cálculo:</strong> aplica el cuadro tarifario al consumo.</li><li><strong>Renglón facturable:</strong> cada concepto a cobrar.</li><li><strong>Factura:</strong> el documento emitido, con su autorización fiscal de ARCA y su talón de pago.</li></ul><p><strong>Frase para decir:</strong> &quot;Así se arma una factura: una persona, su cuenta, sus servicios, lo que consumió, la tarifa que se aplicó y el comprobante autorizado por ARCA. Cada paso queda guardado.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-T12 con código.</span></span>
<span class="line"><span>Título grande: &quot;De la persona a la factura.&quot;</span></span>
<span class="line"><span>Composición: una cadena de tarjetas unidas por flechas finas, en forma de &quot;U&quot; invertida para que entre en la diapositiva. Cada tarjeta tiene un ícono de línea, el nombre en negrita y UNA frase corta debajo (sin nombres de campos):</span></span>
<span class="line"><span>&quot;Persona — una sola vez, aunque cumpla varios roles&quot; → &quot;Titular — responsable de las cuentas&quot; → &quot;Cuenta — los servicios de un titular en un lugar&quot; → &quot;Inmueble — dónde se presta&quot; → &quot;Contrato de servicio — un servicio con su plan vigente&quot; → &quot;Medición — lecturas y consumos&quot; → &quot;Cálculo — la tarifa aplicada al consumo&quot; → &quot;Renglón facturable — cada concepto a cobrar&quot; → &quot;Factura — el comprobante emitido&quot;.</span></span>
<span class="line"><span>De &quot;Factura&quot; salen dos tarjetas chicas: &quot;Autorización fiscal de ARCA&quot; y &quot;Talón de pago&quot;. De &quot;Contrato de servicio&quot; salen dos tarjetas chicas: &quot;Equipos asignados&quot; y &quot;Personas adheridas&quot;.</span></span>
<span class="line"><span>Las tarjetas del recorrido en blanco con borde gris; &quot;Factura&quot; con borde verde grueso.</span></span>
<span class="line"><span>Pie: &quot;Cada paso queda guardado y explica el siguiente&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="img-t13-—-de-la-factura-al-cobro" tabindex="-1">IMG-T13 — De la factura al cobro. <a class="header-anchor" href="#img-t13-—-de-la-factura-al-cobro" aria-label="Permalink to &quot;IMG-T13 — De la factura al cobro.&quot;">​</a></h3><p><strong>Respaldo:</strong> la cuenta corriente, la cobranza y la mora (T05 §7.10):</p><ul><li><strong>Deuda:</strong> cada factura genera una o más deudas en la cuenta corriente del socio, y cada movimiento queda registrado.</li><li><strong>Cobro en caja:</strong> el cajero abre una caja, registra los cobros y emite el recibo. El recibo se imputa contra las deudas que cancela.</li><li><strong>Cobro en línea:</strong> el pago entra por la pasarela y termina en la misma caja.</li><li><strong>Convenio de pago:</strong> refinancia deudas en cuotas que se facturan.</li><li><strong>Mora:</strong> el aviso de mora puede escalar a un caso de corte, y el corte genera órdenes de trabajo para la cuadrilla.</li></ul><p><strong>Frase para decir:</strong> &quot;Cada peso cobrado sabe qué deuda canceló, y cada deuda sabe de qué factura vino.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-T13 con código.</span></span>
<span class="line"><span>Título grande: &quot;De la factura al cobro.&quot;</span></span>
<span class="line"><span>Composición: en el centro, una tarjeta grande &quot;Deuda — lo que el socio debe, de qué factura viene&quot;. A su izquierda, &quot;Factura&quot; con una flecha &quot;origina&quot;. Arriba, &quot;Cuenta corriente — el saldo y todos sus movimientos&quot;, unida a &quot;Deuda&quot;.</span></span>
<span class="line"><span>A la derecha, dos caminos que llegan a la deuda:</span></span>
<span class="line"><span>- &quot;Caja → Cobro → Recibo → Imputación — qué deuda se canceló&quot;</span></span>
<span class="line"><span>- &quot;Pago en línea → Pasarela → misma caja&quot;</span></span>
<span class="line"><span>Abajo, dos ramas en gris:</span></span>
<span class="line"><span>- &quot;Convenio de pago — refinancia deudas en cuotas&quot;</span></span>
<span class="line"><span>- &quot;Aviso de mora → Caso de corte → Orden de trabajo&quot; (este camino con borde ámbar #B7791F).</span></span>
<span class="line"><span>Cada tarjeta con su frase corta, sin nombres de campos.</span></span>
<span class="line"><span>Pie: &quot;Cada peso cobrado sabe qué deuda canceló&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h3 id="img-t14-—-seis-dominios-un-solo-modelo" tabindex="-1">IMG-T14 — Seis dominios, un solo modelo. <a class="header-anchor" href="#img-t14-—-seis-dominios-un-solo-modelo" aria-label="Permalink to &quot;IMG-T14 — Seis dominios, un solo modelo.&quot;">​</a></h3><p><strong>Respaldo:</strong> el mapa de relaciones del modelo se ordena en seis dominios (T05 §7.10).</p><table tabindex="0"><thead><tr><th>Dominio</th><th>Qué contiene</th></tr></thead><tbody><tr><td>Plataforma e identidad</td><td>Cada cooperativa con sus entidades jurídicas (cooperativa, mutual), sus sucursales y puestos. Cada persona que entra al sistema tiene un acceso por cooperativa, con roles asignados</td></tr><tr><td>Núcleo comercial</td><td>Personas, titulares, cuentas, inmuebles, contratos de servicio, equipos, adherentes y asociados (uno por entidad jurídica)</td></tr><tr><td>Medición, tarifa y facturación</td><td>Medidores, lecturas, consumos, cuadros tarifarios, cálculos, facturas y su autorización fiscal</td></tr><tr><td>Cuenta corriente, cobranza y mora</td><td>Deudas, movimientos, cajas, recibos, imputaciones, pagos en línea, convenios, avisos y cortes</td></tr><tr><td>Atención, técnica y stock</td><td>Casos de atención, órdenes de trabajo, materiales, movimientos de stock, equipos con número de serie y red</td></tr><tr><td>ERP administrativo</td><td>Proveedores, compras, facturas de proveedor, pagos, tesorería, asientos contables, empleados y recibos de sueldo</td></tr></tbody></table><p>Todo documento económico o fiscal lleva la entidad jurídica que lo emite (DEC-064).</p><p><strong>Frase para decir:</strong> &quot;Son seis grandes áreas que conversan entre sí. Una factura de agua, un recibo de sueldo y un asiento contable viven en el mismo modelo y se cruzan sin errores.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-T14 con código.</span></span>
<span class="line"><span>Título grande: &quot;Seis dominios, un solo modelo.&quot;</span></span>
<span class="line"><span>Composición: seis bloques grandes dispuestos en hexágono alrededor de un círculo central verde &quot;La cooperativa y sus entidades jurídicas&quot;. Cada bloque tiene un ícono de línea, su nombre y tres o cuatro entidades en palabras simples:</span></span>
<span class="line"><span>1. &quot;Plataforma e identidad&quot; — Cooperativa · Entidades jurídicas · Sucursales · Accesos y roles</span></span>
<span class="line"><span>2. &quot;Núcleo comercial&quot; — Personas · Cuentas · Contratos de servicio · Asociados</span></span>
<span class="line"><span>3. &quot;Medición, tarifa y facturación&quot; — Medidores y lecturas · Tarifas · Facturas · Autorización ARCA</span></span>
<span class="line"><span>4. &quot;Cuenta corriente y cobranza&quot; — Deudas · Cajas y recibos · Pagos en línea · Convenios y mora</span></span>
<span class="line"><span>5. &quot;Atención, técnica y stock&quot; — Casos · Órdenes de trabajo · Materiales · Equipos y red</span></span>
<span class="line"><span>6. &quot;ERP administrativo&quot; — Proveedores y compras · Tesorería · Contabilidad · Sueldos</span></span>
<span class="line"><span>Entre bloques vecinos, líneas finas grises que muestran que se relacionan (por ejemplo, de &quot;Núcleo comercial&quot; a &quot;Facturación&quot;, de &quot;Facturación&quot; a &quot;Cobranza&quot;, de &quot;Cobranza&quot; a &quot;ERP administrativo&quot;).</span></span>
<span class="line"><span>Pie: &quot;Todo documento económico lleva la entidad jurídica que lo emite&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h3 id="img-t15-—-reglas-que-valen-para-todos-los-datos" tabindex="-1">IMG-T15 — Reglas que valen para todos los datos. <a class="header-anchor" href="#img-t15-—-reglas-que-valen-para-todos-los-datos" aria-label="Permalink to &quot;IMG-T15 — Reglas que valen para todos los datos.&quot;">​</a></h3><p><strong>Respaldo:</strong> son las convenciones obligatorias para todas las tablas (T05 §6 y §7.1; DEC-117).</p><table tabindex="0"><thead><tr><th>Regla</th><th>Qué protege</th></tr></thead><tbody><tr><td>Cada dato lleva su cooperativa</td><td>Que nunca se mezclen cooperativas</td></tr><tr><td>El dinero se guarda con precisión decimal exacta, nunca como número aproximado</td><td>Que no aparezcan centavos de diferencia</td></tr><tr><td>Los documentos económicos no se borran ni se editan: se corrigen con un documento contrario</td><td>Que la historia contable sea siempre la misma</td></tr><tr><td>Lo emitido guarda una foto de los datos de ese momento</td><td>Que una factura vieja se reimprima igual aunque el socio se haya mudado</td></tr><tr><td>Cada cambio registra quién, cuándo y qué cambió, y dos personas no pueden pisarse</td><td>Auditoría y trabajo simultáneo seguro</td></tr><tr><td>Los datos personales están clasificados; los sensibles (salud, electrodependencia, sindicales, judiciales) y los bancarios se cifran</td><td>Privacidad (Ley 25.326)</td></tr><tr><td>Ninguna contraseña ni certificado se guarda en los datos del negocio: van a una bóveda cifrada</td><td>Que un acceso a la base no exponga credenciales</td></tr><tr><td>Lo migrado del sistema actual conserva la referencia a su registro de origen</td><td>Poder verificar cada dato migrado</td></tr><tr><td>Las referencias se declaran en Azure SQL (FK e índices) donde el dueño lo define, más cinco mecanismos en aplicación y un verificador nocturno que informa sin corregir (DEC-100, DEC-117)</td><td>Que no queden datos huérfanos</td></tr></tbody></table><p><strong>Frase para decir:</strong> &quot;Estas reglas no se eligen módulo por módulo: valen para todo el sistema, desde el primer día.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-T15 con código.</span></span>
<span class="line"><span>Título grande: &quot;Reglas que valen para todos los datos.&quot;</span></span>
<span class="line"><span>Composición: una cuadrícula de 3 × 3 tarjetas iguales, cada una con un ícono de línea, una regla corta en negrita y, debajo, qué protege en gris:</span></span>
<span class="line"><span>&quot;Cada dato lleva su cooperativa&quot; — nunca se mezclan ·</span></span>
<span class="line"><span>&quot;Dinero con precisión exacta&quot; — sin centavos de diferencia ·</span></span>
<span class="line"><span>&quot;Lo económico no se borra&quot; — se corrige con un documento contrario ·</span></span>
<span class="line"><span>&quot;Foto de lo emitido&quot; — una factura vieja se reimprime igual ·</span></span>
<span class="line"><span>&quot;Quién, cuándo y qué&quot; — y nadie pisa el trabajo de otro ·</span></span>
<span class="line"><span>&quot;Datos sensibles cifrados&quot; — salud, bancarios, judiciales ·</span></span>
<span class="line"><span>&quot;Credenciales en bóveda&quot; — nunca en los datos del negocio ·</span></span>
<span class="line"><span>&quot;Traza de lo migrado&quot; — cada dato con su origen ·</span></span>
<span class="line"><span>&quot;Referencias verificadas cada noche&quot; — se informa, no se corrige solo.</span></span>
<span class="line"><span>Las tarjetas con borde gris claro y el ícono en verde.</span></span>
<span class="line"><span>Pie: &quot;Obligatorias para las 1.058 tablas, desde la ola O0&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><h3 id="img-t16-—-pensado-para-crecer" tabindex="-1">IMG-T16 — Pensado para crecer. <a class="header-anchor" href="#img-t16-—-pensado-para-crecer" aria-label="Permalink to &quot;IMG-T16 — Pensado para crecer.&quot;">​</a></h3><p><strong>Respaldo:</strong> el modelo está dimensionado para crecer (DEC-075; T05 §7.8.2).</p><ul><li><strong>Tamaño de las cooperativas:</strong> una estándar tiene 25.000 suministros y una grande, 150.000.</li><li><strong>Cantidad de cooperativas:</strong> el diseño es para 100 cooperativas y llega hasta 300 sin rediseño.</li><li><strong>Volumen de facturas:</strong> una cooperativa estándar emite unas 0,4 millones de facturas por año y una grande, 2,3 millones.</li><li><strong>Crecimiento:</strong> las tablas de alto volumen nacen con índices por cooperativa y partición lógica por tenant; el modelo escala en Azure SQL sin reescribir relaciones (DEC-075).</li><li><strong>Archivo en frío:</strong> el detalle accesorio de más de 36 meses se archiva cifrado por cooperativa.</li><li><strong>Lo que no se archiva:</strong> facturas, recibos, asientos y movimientos quedan en línea los 10 años, y el saldo de una cuenta nunca depende del archivo.</li></ul><p><strong>Frase para decir:</strong> &quot;No diseñamos para la primera cooperativa: diseñamos para cien, y el modelo aguanta trescientas sin rehacerlo.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-T16 con código.</span></span>
<span class="line"><span>Título grande: &quot;Pensado para crecer.&quot;</span></span>
<span class="line"><span>Composición en tres columnas:</span></span>
<span class="line"><span>1. &quot;Tamaño&quot;: dos círculos, uno chico &quot;25.000 suministros · cooperativa estándar&quot; y uno grande &quot;150.000 · cooperativa grande&quot;; debajo, &quot;0,4 M y 2,3 M facturas por año&quot;.</span></span>
<span class="line"><span>2. &quot;Escala&quot;: una fila de 100 puntos pequeños verdes y, a continuación, puntos grises hasta completar 300, con el rótulo &quot;Diseñado para 100 · hasta 300 sin rediseño&quot;. Debajo, &quot;Preparado para repartirse por cooperativa; las grandes en su propio espacio&quot;.</span></span>
<span class="line"><span>3. &quot;Archivo&quot;: una línea de tiempo de 10 años; los primeros 36 meses en verde &quot;en línea&quot;, el resto en gris &quot;detalle accesorio archivado y cifrado&quot;. Encima de toda la línea, una franja verde fina: &quot;Facturas, recibos, asientos y movimientos: en línea los 10 años&quot;.</span></span>
<span class="line"><span>Pie: &quot;El saldo de una cuenta nunca depende del archivo&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><hr><h2 id="_6-notas-para-el-presentador" tabindex="-1">6. Notas para el presentador <a class="header-anchor" href="#_6-notas-para-el-presentador" aria-label="Permalink to &quot;6. Notas para el presentador&quot;">​</a></h2><ul><li><strong>Para una reunión comercial:</strong> T01, T02, T03 y T04, y para cerrar T12 y T15.</li><li><strong>Para una reunión técnica:</strong> T05 a T10 completos, y después T11, T14, T15 y T16.</li><li><strong>Si solo hay lugar para cinco:</strong> T01, T05, T09, T12 y T15.</li><li><strong>El dominio propio de la cooperativa</strong> está previsto, pero queda a validar (PA-POR-12 y PA-PLA-11). En T01 aparece como una opción, no como un hecho.</li><li><strong>Los colores de las cooperativas de ejemplo</strong> son los de la precarga ficticia de M19 §18.1. La tercera cooperativa de T01 es solo ilustrativa.</li><li><strong>En el modelo de datos no se muestran campos ni tipos.</strong> El detalle campo por campo vive en el §7 de cada anexo dueño, y T05 tiene el catálogo completo. Si alguien técnico lo pide, se muestra el anexo y no se agranda la imagen.</li><li><strong>Las cifras de volumen de T16</strong> son órdenes de magnitud para dimensionar el modelo, no metas de rendimiento (T05 §7.8.2).</li></ul>`,117)])])}const b=e(t,[["render",r]]);export{m as __pageData,b as default};
